#!/bin/sh
# Generated by image-composer-tool. Shows a failed provisioning script at the
# login prompt and after login.
#
# Called by the script's unit:
#   failed NAME UNIT   ExecStopPost: records a failure
#   ok NAME            ExecStartPost: removes a recorded failure
set -u

# This runs as root with the script's environment, and a template may set the
# script's PATH (to a user's directory, or to one without the system
# directories). Use only the system directories, with /usr/bin first: the
# utilities this uses are there, so a script installed under another name in
# /usr/local/bin or /usr/sbin (for example one called rm) cannot take their place.
PATH=/usr/bin:/bin:/usr/sbin:/sbin
export PATH

state=/var/lib/image-composer-tool
etc=/etc
usage="usage: $0 failed NAME UNIT | ok NAME"
cmd="${1:-}"
name="${2:-}"
case "$name" in
'' | .* | -* | *[!A-Za-z0-9_.-]*)
	echo "$usage" >&2
	exit 2
	;;
esac
issue="$etc/issue.d/ict-provision-$name.issue"
motd="$etc/motd.d/ict-provision-$name"

case "$cmd" in
ok) rm -f "$issue" "$motd" ;;
failed)
	[ "${SERVICE_RESULT:-success}" != success ] || exit 0
	# Stopped because the system is rebooting or shutting down, for example when
	# the script reboots it to finish a step: not a failure, the script runs
	# again after the boot. Only a termination by the shutdown counts: systemd
	# ends the script with SIGTERM, which shows up as exit status 143 when the
	# script traps it, or as the TERM signal. Any other failure while the system
	# is stopping, such as a script exiting 1 or a timeout, is still recorded.
	if [ "$(systemctl is-system-running 2>/dev/null)" = stopping ]; then
		case "${SERVICE_RESULT:-}/${EXIT_STATUS:-}" in
		exit-code/143 | signal/TERM | signal/15) exit 0 ;;
		esac
	fi
	# A unit can fail after its script succeeded and the stamp was written (for
	# example when rebootAfter's reboot command fails). Take the stamp back so the
	# script runs again, as the notice says.
	stamp="$state/provisioned/$name"
	rm -f "$stamp"
	unit="${3:-ict-provision-$name.service}"
	mkdir -p "$etc/issue.d" "$etc/motd.d"
	notice() {
		printf '\n*** Provisioning script "%s" failed. ***\n' "$name"
		printf 'Please look at the journal logs: sudo journalctl -u %s\n' "$unit"
		if [ -e "$stamp" ]; then
			# The unit stays skipped while the stamp exists.
			printf 'It cannot run again until its completion record is removed: %s\n\n' "$stamp"
		else
			printf 'It runs again at the next boot if the scripts before it succeed.\n\n'
		fi
	}
	# Write each notice to a new temporary file in /etc (which neither agetty nor
	# pam_motd reads) and move it into place only when the write succeeded, so a
	# failed write keeps the earlier notice. The two notices are independent.
	# mktemp creates the file exclusively, so it cannot be one the template installed.
	written=0
	for dest in "$issue" "$motd"; do
		tmp=""
		if tmp="$(mktemp "$etc/.ict-provision-$name.XXXXXX")" &&
			notice >"$tmp" && chmod 0644 "$tmp" && mv -f "$tmp" "$dest"; then
			written=1
		elif [ -n "$tmp" ]; then
			rm -f "$tmp"
		fi
	done
	if [ "$written" -eq 0 ]; then
		echo "ict-provision-report: cannot write the failure notice for $name" >&2
		exit 1
	fi
	;;
*)
	echo "$usage" >&2
	exit 2
	;;
esac
